#include <string>
#include <regex>

std::string markdownToHtml(const std::string& markdown) {
    // Replace markdown tags with HTML tags
    std::string html = markdown;
    std::regex pattern(R"(^#*(\d+)(.*?))");
    std::regex_replace(html, pattern, "<h1>$1</h1>$3");
    std::regex_replace(html, pattern, "<h2>$1</h2>$3");
    std::regex_replace(html, pattern, "<h3>$1</h3>$3");
    std::regex_replace(html, pattern, "<h4>$1</h4>$3");
    std::regex_replace(html, pattern, "<h5>$1</h5>$3");
    std::regex_replace(html, pattern, "<h6>$1</h6>$3");
    std::regex_replace(html, pattern, "<h7>$1</h7>$3");
    return html;
}
```

